// ============================================================================
// ELEC4020 / ELEC5200 - Lab 3, Exercise 3
// Measure the frequency of the PF2 square wave (generated by Exercise 2)
// using Timer1A in edge-time capture mode, and display it on a
// common-cathode 3-digit 7-segment display.
//
// Wiring:
//   PB4 (T1CCP0)  <--  PF2  (signal to measure)
//   7-seg segments: A=PC4 B=PC6 C=PE2 D=PD3 E=PD2 F=PC5 G=PC7 DP=PE1
//   7-seg digits  : DIG1=PA2 DIG2=PA3 DIG3=PA4 (active-high, via NPN)
// ============================================================================

#include <stdint.h>
#include <stdbool.h>
#include "inc/tm4c123gh6pm.h"
#include "inc/hw_memmap.h"
#include "inc/hw_types.h"
#include "inc/hw_ints.h"
#include "inc/hw_gpio.h"
#include "driverlib/sysctl.h"
#include "driverlib/interrupt.h"
#include "driverlib/gpio.h"
#include "driverlib/timer.h"
#include "driverlib/pin_map.h"

// ---------------------------------------------------------------------------
// Function prototypes
// ---------------------------------------------------------------------------
void Timer1AIntHandler(void);
void SysTickIntHandler(void);

// ---------------------------------------------------------------------------
// Globals
// ---------------------------------------------------------------------------
volatile uint32_t g_ui32Clock;              // system clock (Hz)

volatile uint32_t g_ui32LastCapture = 0;    // previous capture value
volatile bool     g_bFirstCapture  = true;  // discard the first edge
volatile uint32_t g_ui32Frequency_x10 = 0;  // measured frequency * 10 (e.g. 55 = 5.5 Hz)

// 7-segment digit buffer: [0] = tenths, [1] = units, [2] = decimal point digit
// We display "X.YZ" -> up to 9.99; here we only need 0.5 .. 9.5, so we use
// the format  "X.Y "  (tenths + '.' + units), with leading zero suppressed.
volatile uint8_t  g_ui8Display[3] = {0, 0, 0};

// ---------------------------------------------------------------------------
// 7-segment encoding (common cathode, active-high segments)
// bit0=A bit1=B bit2=C bit3=D bit4=E bit5=F bit6=G bit7=DP
// ---------------------------------------------------------------------------
static const uint8_t kSegCode[10] = {
    0x3F, // 0 : A B C D E F
    0x06, // 1 : B C
    0x5B, // 2 : A B D E G
    0x4F, // 3 : A B C D G
    0x66, // 4 : B C F G
    0x6D, // 5 : A C D F G
    0x7D, // 6 : A C D E F G
    0x07, // 7 : A B C
    0x7F, // 8 : A B C D E F G
    0x6F  // 9 : A B C D F G
};
#define SEG_DP  0x80

// ===========================================================================
// main
// ===========================================================================
int main(void)
{
    // -----------------------------------------------------------------------
    // 1. System clock: 40 MHz
    // -----------------------------------------------------------------------
    SysCtlClockSet(SYSCTL_SYSDIV_5 | SYSCTL_USE_PLL |
                   SYSCTL_XTAL_16MHZ | SYSCTL_OSC_MAIN);
    g_ui32Clock = SysCtlClockGet();

    // -----------------------------------------------------------------------
    // 2. Enable peripherals
    // -----------------------------------------------------------------------
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOA);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOC);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOD);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOE);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_GPIOB);
    SysCtlPeripheralEnable(SYSCTL_PERIPH_TIMER1);

    // -----------------------------------------------------------------------
    // 3. Configure 7-segment segment pins as outputs
    //    A=PC4 B=PC6 C=PE2 D=PD3 E=PD2 F=PC5 G=PC7 DP=PE1
    // -----------------------------------------------------------------------
    GPIOPinTypeGPIOOutput(GPIO_PORTC_BASE, GPIO_PIN_4 | GPIO_PIN_5 | GPIO_PIN_6 | GPIO_PIN_7);
    GPIOPinTypeGPIOOutput(GPIO_PORTD_BASE, GPIO_PIN_2 | GPIO_PIN_3);
    GPIOPinTypeGPIOOutput(GPIO_PORTE_BASE, GPIO_PIN_1 | GPIO_PIN_2);

    // -----------------------------------------------------------------------
    // 4. Configure digit-select pins as outputs
    //    DIG1=PA2 DIG2=PA3 DIG3=PA4
    // -----------------------------------------------------------------------
    GPIOPinTypeGPIOOutput(GPIO_PORTA_BASE, GPIO_PIN_2 | GPIO_PIN_3 | GPIO_PIN_4);
    GPIOPinWrite(GPIO_PORTA_BASE, GPIO_PIN_2 | GPIO_PIN_3 | GPIO_PIN_4, 0);

    // -----------------------------------------------------------------------
    // 5. PB4 as Timer1 capture input (T1CCP0)
    // -----------------------------------------------------------------------
    GPIOPinConfigure(GPIO_PB4_T1CCP0);
    GPIOPinTypeTimer(GPIO_PORTB_BASE, GPIO_PIN_4);

    // -----------------------------------------------------------------------
    // 6. Timer1A: 32-bit edge-time capture, rising edge
    // -----------------------------------------------------------------------
    TimerConfigure(TIMER1_BASE, TIMER_CFG_ONE_SHOT_UP);
    // Re-configure properly as a capture timer:
    TimerConfigure(TIMER1_BASE, TIMER_CFG_SPLIT_PAIR | TIMER_CFG_A_CAP_TIME_UP);
    TimerControlEvent(TIMER1_BASE, TIMER_A, TIMER_EVENT_POS_EDGE);
    TimerLoadSet(TIMER1_BASE, TIMER_A, 0xFFFFFFFF);   // 32-bit free-run
    TimerEnable(TIMER1_BASE, TIMER_A);

    TimerIntRegister(TIMER1_BASE, TIMER_A, Timer1AIntHandler);
    TimerIntEnable(TIMER1_BASE, TIMER_CAPA_EVENT);
    IntEnable(INT_TIMER1A);

    // -----------------------------------------------------------------------
    // 7. SysTick: 10 ms tick, used for (a) display multiplexing
    //    and (b) periodic refresh of the measured value on the display
    // -----------------------------------------------------------------------
    SysTickPeriodSet(g_ui32Clock / 100 - 1);   // 10 ms
    SysTickIntEnable();
    SysTickEnable();

    // -----------------------------------------------------------------------
    // 8. Global interrupts
    // -----------------------------------------------------------------------
    IntMasterEnable();

    // -----------------------------------------------------------------------
    // 9. Main loop
    // -----------------------------------------------------------------------
    while (1) { }
}

// ===========================================================================
// Timer1A capture ISR: one rising edge per full period
// ===========================================================================
void Timer1AIntHandler(void)
{
    TimerIntClear(TIMER1_BASE, TIMER_CAPA_EVENT);

    uint32_t current = TimerValueGet(TIMER1_BASE, TIMER_A);

    if (g_bFirstCapture)
    {
        // First edge: no reference yet — discard
        g_bFirstCapture = false;
        g_ui32LastCapture = current;
        return;
    }

    // 32-bit timer: simple unsigned difference; wrap handled by 2^32
    uint32_t period = current - g_ui32LastCapture;
    g_ui32LastCapture = current;

    // Guard against noise / missed edges
    if (period == 0U) return;

    // frequency in 0.1 Hz units:  f_x10 = clock * 10 / period
    uint32_t freq_x10 = (g_ui32Clock * 10U) / period;

    // Clamp to the displayable / expected range 0.5 .. 9.5 Hz
    if (freq_x10 < 5U)   freq_x10 = 5U;
    if (freq_x10 > 95U)  freq_x10 = 95U;

    g_ui32Frequency_x10 = freq_x10;

    // Format for display:  "X.Y"  (only 2 significant digits needed)
    // digit[0] = tenths (integer part), digit[1] = units (fractional tenths)
    // We display  "d0.d1"  with the decimal point on digit 1.
    uint32_t f = g_ui32Frequency_x10;
    g_ui8Display[0] = (uint8_t)(f / 10U);        // integer part  (0..9)
    g_ui8Display[1] = (uint8_t)(f % 10U);        // tenths        (0..9)
    g_ui8Display[2] = 0;                         // blank
}

// ===========================================================================
// SysTick ISR (10 ms): multiplex the 3-digit display
// ===========================================================================
void SysTickIntHandler(void)
{
    static uint8_t digit = 0;

    // Turn all digits off first (avoid ghosting)
    GPIOPinWrite(GPIO_PORTA_BASE, GPIO_PIN_2 | GPIO_PIN_3 | GPIO_PIN_4, 0);

    // Build the segment byte for the current digit
    uint8_t value = g_ui8Display[digit];
    uint8_t segs;
    if (value > 9U) segs = 0x00;                 // blank
    else            segs = kSegCode[value];

    // Insert decimal point on digit 1 (between "X" and ".Y")
    if (digit == 1) segs |= SEG_DP;

    // Push segments onto PC/PD/PE
    // A=PC4 bit0  B=PC6 bit1  C=PE2 bit2  D=PD3 bit3
    // E=PD2 bit4  F=PC5 bit5  G=PC7 bit6  DP=PE1 bit7
    uint32_t portC = 0, portD = 0, portE = 0;
    if (segs & 0x01) portC |= GPIO_PIN_4;  // A
    if (segs & 0x02) portC |= GPIO_PIN_6;  // B
    if (segs & 0x04) portE |= GPIO_PIN_2;  // C
    if (segs & 0x08) portD |= GPIO_PIN_3;  // D
    if (segs & 0x10) portD |= GPIO_PIN_2;  // E
    if (segs & 0x20) portC |= GPIO_PIN_5;  // F
    if (segs & 0x40) portC |= GPIO_PIN_7;  // G
    if (segs & 0x80) portE |= GPIO_PIN_1;  // DP

    GPIOPinWrite(GPIO_PORTC_BASE, GPIO_PIN_4|GPIO_PIN_5|GPIO_PIN_6|GPIO_PIN_7, portC);
    GPIOPinWrite(GPIO_PORTD_BASE, GPIO_PIN_2|GPIO_PIN_3, portD);
    GPIOPinWrite(GPIO_PORTE_BASE, GPIO_PIN_1|GPIO_PIN_2, portE);

    // Enable the current digit (active-high through NPN)
    uint32_t digitMask = 0;
    if (digit == 0) digitMask = GPIO_PIN_2;      // DIG1 = PA2
    if (digit == 1) digitMask = GPIO_PIN_3;      // DIG2 = PA3
    if (digit == 2) digitMask = GPIO_PIN_4;      // DIG3 = PA4
    GPIOPinWrite(GPIO_PORTA_BASE, digitMask, digitMask);

    digit = (digit + 1U) % 3U;
}
